"""What audio effects cost: runs benchmarks/audio_effects.bb with every setup in turn (interleaved, so drift hits all of them alike) and
prints the CPU time of the process per second of sound, and what each setup adds to "none" (the same sounds without effects), also as a
share of one core.

    python3 benchmarks/audio_effects.py [--blitzcc PATH] [--rounds 7] [--channels 32] [--play-ms 5000] [--setups none,bus-reverb,...]

The sound plays on the system's default device (SDL_AUDIODRIVER as set; "dummy" mixes at real-time pace without a device)."""
import argparse
import ctypes
import math
import os
import platform
import statistics
import struct
import subprocess
import sys
import tempfile
import time
import wave

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import benchutil  # noqa: E402

SETUPS = ["none", "bus-filters", "bus-echo", "bus-reverb", "bus-chain", "channel-lowpass", "channel-chain", "sends-reverb", "air"]


def cpu_seconds(command, env, cwd, timeout):
    """Runs a program and gives the CPU time (user and kernel) that it took, and its output."""
    p = subprocess.Popen(command, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
    if platform.system() == "Windows":
        out, _ = p.communicate(timeout=timeout)
        times = [ctypes.c_ulonglong() for _ in range(4)]
        ctypes.windll.kernel32.GetProcessTimes(int(p._handle), *[ctypes.byref(t) for t in times])
        return (times[2].value + times[3].value) / 1e7, out.decode(errors="replace"), p.returncode
    import resource
    before = resource.getrusage(resource.RUSAGE_CHILDREN)
    out, _ = p.communicate(timeout=timeout)
    after = resource.getrusage(resource.RUSAGE_CHILDREN)
    return (after.ru_utime - before.ru_utime) + (after.ru_stime - before.ru_stime), out.decode(errors="replace"), p.returncode


def make_sound(path):
    """Two seconds of a stereo tone with some noise in it, at 44.1 kHz, so the filters have something to do."""
    with wave.open(path, "wb") as out:
        out.setnchannels(2)
        out.setsampwidth(2)
        out.setframerate(44100)
        frames = bytearray()
        seed = 1
        for i in range(88200):
            seed = (seed * 1103515245 + 12345) & 0x7FFFFFFF
            v = 0.3 * math.sin(2 * math.pi * 220 * i / 44100) + 0.1 * (seed / 0x7FFFFFFF - 0.5)
            frames += struct.pack("<hh", int(v * 32767), int(v * 32767))
        out.writeframes(bytes(frames))


def main():
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--blitzcc")
    parser.add_argument("--rounds", type=int, default=7)
    parser.add_argument("--channels", type=int, default=32)
    parser.add_argument("--play-ms", type=int, default=5000)
    parser.add_argument("--setups", default=",".join(SETUPS))
    args = parser.parse_args()
    setups = args.setups.split(",")
    if "none" not in setups:
        setups.insert(0, "none")
    compiler = benchutil.find_compiler(args.blitzcc)
    with tempfile.TemporaryDirectory() as d:
        sound = os.path.join(d, "sound.wav")
        make_sound(sound)
        benchutil.copy_synced(os.path.join(HERE, "audio_effects.bb"), os.path.join(d, "audio_effects.bb"))
        program = benchutil.program_path(d)
        r = subprocess.run([compiler, "audio_effects.bb", "-o", program], cwd=d, capture_output=True, text=True)
        if r.returncode != 0 or not os.path.isfile(program):
            sys.exit("Compiling failed:\n" + r.stdout + r.stderr)
        results = {s: [] for s in setups}
        for round_index in range(args.rounds):
            order = setups if round_index % 2 == 0 else list(reversed(setups))
            for setup in order:
                env = dict(os.environ, BENCH_SOUND=sound, BENCH_SETUP=setup, BENCH_CHANNELS=str(args.channels), BENCH_PLAY_MS=str(args.play_ms))
                cpu, out, code = cpu_seconds([program], env, d, timeout=args.play_ms / 1000 + 120)
                if code != 0 or "RESULT" not in out:
                    sys.exit("%s failed (exit %s): %s" % (setup, code, out[-400:]))
                results[setup].append(cpu / (args.play_ms / 1000.0) * 1000.0)
            print("round %d of %d done" % (round_index + 1, args.rounds), file=sys.stderr)
    base = statistics.median(results["none"])
    print("%d channels, %d ms each, %d rounds; CPU ms per second of sound (median, min to max), and what the setup adds to none" %
          (args.channels, args.play_ms, args.rounds))
    print("%-16s %10s %20s %12s %10s" % ("setup", "ms/s", "range", "added ms/s", "% of core"))
    for setup in setups:
        values = results[setup]
        median = statistics.median(values)
        added = median - base
        print("%-16s %10.2f %9.2f to %8.2f %12.2f %9.2f%%" % (setup, median, min(values), max(values), added, added / 10.0))


if __name__ == "__main__":
    main()
